package org.marketreview.nativeapp;
import android.content.Context;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.View;
import android.widget.*;
import java.io.File;
import java.util.*;
import org.json.*;
/** Offline plain-text evidence review and explicitly approved independent candidates. */
final class EvidenceReviewScreen extends LinearLayout {
 interface Instruments{JSONArray current()throws Exception;}
 interface Action{void open(String action,JSONObject exactInstrument)throws Exception;}
 interface Work{void run()throws Exception;}
 final Context context;final BusinessStore business;final EvidenceReviewStore store;final Instruments instruments;final Action action;final SourceHandoffPanel.Opener opener;
 SourceHandoffPanel.Exporter exporter;Runnable chooser;final ScrollView mainScroll;final LinearLayout main,reportList,batchList,candidateList,evidenceList;ScrollView reader;int readerY;boolean dark,loading;
 final TextView status,previewText;final EditText input,identity;final CheckBox acknowledge;JSONObject pending=new JSONObject(),report=new JSONObject();String previewRevision="",draftRevision="";final TreeMap<Integer,JSONObject> selected=new TreeMap<>();int reportOffset,batchOffset;
 EvidenceReviewScreen(Context c,BusinessStore b,File db,Instruments i,Action a,SourceHandoffPanel.Opener o)throws Exception{super(c);context=c;business=b;store=new EvidenceReviewStore(db);instruments=i;action=a;opener=o;setOrientation(VERTICAL);mainScroll=new ScrollView(c);addView(mainScroll,new LayoutParams(-1,-1));main=vertical();mainScroll.addView(main);status=text("人工导入待核验研究材料；无模型调用；候选只保存独立历史");main.addView(status);input=input("完整报告 JSON、旧 researchRuns、候选 JSON / Markdown / 文本",7);main.addView(input);main.addView(button("选择本机报告 / 旧导出",()->{EvidenceReviewModel.require(chooser!=null,"宿主未接文件选择");chooser.run();}));main.addView(button("预览粘贴材料（尚未合并）",()->previewImport(input.getText().toString())));previewText=text("");main.addView(previewText);main.addView(button("阅读完整待合并预览",()->read(EvidenceReviewModel.json(pending))));main.addView(button("明确合并报告 / 恢复已确认备份",()->{EvidenceReviewModel.require(pending.length()>0,"请先预览");JSONObject result=store.merge(pending,previewRevision);pending=new JSONObject();previewRevision=result.optString("previewRevision");renderPreview();refresh();status.setText("合并 "+result.optInt("added")+" · 重复 "+result.optInt("duplicate")+" · 冲突保留本机 "+result.optInt("conflict"));}));main.addView(button("取消待合并预览",()->{JSONObject row=store.stage(new JSONObject(),previewRevision);previewRevision=row.getString("recordRevision");pending=new JSONObject();renderPreview();}));main.addView(button("导出已确认完整备份",()->{EvidenceReviewModel.require(exporter!=null,"宿主未接文件保存");exporter.write("evidence-review.json","application/json",store.backup());}));main.addView(text("报告与引用（已有研究只读）"));reportList=vertical();main.addView(reportList);main.addView(button("报告上一页",()->{reportOffset=Math.max(0,reportOffset-50);refreshReports();}));main.addView(button("报告下一页",()->{if(store.list("reports",reportOffset).length()==50){reportOffset+=50;refreshReports();}}));main.addView(button("重读本机研究报告",this::refreshReports));main.addView(button("阅读完整报告 / 提示词 / 旧原记录",()->{EvidenceReviewModel.require(report.length()>0,"请选择报告");read(EvidenceReviewModel.readReport(report));}));evidenceList=vertical();main.addView(evidenceList);main.addView(text("候选行（重复原行保留，人工取舍）"));candidateList=vertical();main.addView(candidateList);identity=input("完整身份，例如 SH:stock:600000；不猜测市场/类型",1);main.addView(identity);acknowledge=new CheckBox(c);acknowledge.setText("已阅读核验状态；这些 AI 材料和引用仍未独立验证，仅保存研究候选");main.addView(acknowledge);main.addView(button("明确确认所选候选并保存独立历史",()->{EvidenceReviewModel.require(store.get("reports",report.optString("id")).length()>0,"已有研究只读：请导出该报告后明确导入，再保存独立候选");JSONArray rows=new JSONArray();for(JSONObject row:selected.values())rows.put(row);String referenceReview=EvidenceReviewModel.reviewText(report,rows,business.read("docs"),business.read("collections"));store.approve(report.getString("id"),rows,acknowledge.isChecked(),catalogue());selected.clear();markSelections();persist();refreshHistory();status.setText("独立候选历史已保存；加入自选/K线须另行明确动作\n"+referenceReview);}));main.addView(button("明确取消全部候选选择（保留报告 / 输入）",()->{selected.clear();markSelections();persist();status.setText("已明确取消全部候选选择");}));main.addView(text("已确认候选历史"));batchList=vertical();main.addView(batchList);main.addView(button("历史上一页",()->{batchOffset=Math.max(0,batchOffset-50);refreshHistory();}));main.addView(button("历史下一页",()->{if(store.list("batches",batchOffset).length()==50){batchOffset+=50;refreshHistory();}}));
 main.addView(button("重读共享草稿与预览（明确替换当前编辑）",this::restoreWorkspace));restoreWorkspace();TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!loading)safe(()->persist());}public void afterTextChanged(Editable e){}};input.addTextChangedListener(watcher);identity.addTextChangedListener(watcher);acknowledge.setOnCheckedChangeListener((v,checked)->{if(!loading)safe(()->persist());});}
 void restoreWorkspace()throws Exception{loading=true;try{selected.clear();JSONObject staged=store.get("previews","import-preview");pending=EvidenceReviewModel.obj(staged,"preview");previewRevision=staged.optString("recordRevision");JSONObject draft=store.get("drafts","workspace");draftRevision=draft.optString("recordRevision");input.setText(draft.optString("input"));identity.setText(draft.optString("identity"));acknowledge.setChecked(draft.optBoolean("acknowledged"));JSONObject old=store.get("reports",draft.optString("reportId"));if(old.length()==0&&EvidenceReviewModel.obj(draft,"reportSnapshot").length()>0){old=EvidenceReviewModel.validate(draft.getJSONObject("reportSnapshot"));status.setText("已恢复报告草稿快照；若本机原报告缺失，不当作当前来源打开");}if(old.length()>0)loadReport(old);else{report=new JSONObject();evidenceList.removeAllViews();candidateList.removeAllViews();}JSONArray choices=EvidenceReviewModel.arr(draft,"selections");for(int n=0;n<choices.length();n++)selected.put(choices.getJSONObject(n).getInt("row"),choices.getJSONObject(n));markSelections();refresh();renderPreview();}finally{loading=false;}}
 void markSelections(){for(int n=0;n<candidateList.getChildCount();n+=4){View child=candidateList.getChildAt(n);if(child instanceof TextView){TextView label=(TextView)child;String body=label.getText().toString().replace("已选择 · ","");label.setText(selected.containsKey(n/4)?"已选择 · "+body:body);}}}
 LinearLayout vertical(){LinearLayout v=new LinearLayout(context);v.setOrientation(VERTICAL);v.setPadding(12,8,12,8);return v;}
 TextView text(String s){TextView v=new TextView(context);v.setText(s);v.setTextIsSelectable(true);return v;}
 EditText input(String hint,int lines){EditText v=new EditText(context);v.setHint(hint);v.setMinLines(lines);v.setGravity(android.view.Gravity.TOP);return v;}
 Button button(String label,Work work){Button b=new Button(context);b.setText(label);b.setOnClickListener(v->safe(work));return b;}
 void safe(Work work){try{work.run();style();}catch(Exception e){status.setText(e.getMessage());}}
 JSONArray catalogue()throws Exception{return instruments==null?new JSONArray():instruments.current();}
 void setFileActions(SourceHandoffPanel.Exporter e,Runnable choose){exporter=e;chooser=choose;}
 void previewImport(String json)throws Exception{JSONObject prepared=store.preview(json),staged=store.stage(prepared,previewRevision);pending=prepared;previewRevision=staged.getString("recordRevision");renderPreview();}
 void renderPreview(){previewText.setText(pending.length()==0?"暂无待合并预览":"可恢复预览草稿；尚未合并证据\n新增 "+pending.optInt("newCount")+" · 重复 "+pending.optInt("duplicateCount")+" · 冲突 "+pending.optInt("conflictCount"));}
 void persist()throws Exception{JSONArray choices=new JSONArray();for(JSONObject row:selected.values())choices.put(row);JSONObject draft=store.put(new JSONObject().put("kind","drafts").put("id","workspace").put("input",input.getText().toString()).put("identity",identity.getText().toString()).put("reportId",report.optString("id")).put("reportSnapshot",report).put("selections",choices).put("acknowledged",acknowledge.isChecked()),draftRevision);draftRevision=draft.getString("recordRevision");}
 void refresh()throws Exception{refreshReports();refreshHistory();}
 void refreshReports()throws Exception{reportList.removeAllViews();JSONArray rows=store.list("reports",reportOffset);for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);reportList.addView(button("已导入 · "+r.optString("title"),()->selectReport(store.get("reports",r.getString("id")))));}if(reportOffset==0){JSONArray history=business.read("reports");for(int n=0;n<history.length();n++){JSONObject r=history.getJSONObject(n);if(!r.optString("legacySource").equals("ai_research_runs"))continue;JSONObject normalized=EvidenceReviewModel.decode(EvidenceReviewModel.json(r)).getJSONObject(0);reportList.addView(button("已有研究（只读） · "+normalized.getString("title"),()->selectReport(normalized)));}}}
 void selectReport(JSONObject r)throws Exception{if(r.optString("id").equals(report.optString("id")))return;EvidenceReviewModel.require(selected.isEmpty()||r.optString("id").equals(report.optString("id")),"尚有选择草稿，请保存或明确取消选择后切换报告");loadReport(r);persist();}
 void loadReport(JSONObject r)throws Exception{r=EvidenceReviewModel.validate(r);report=r;selected.clear();evidenceList.removeAllViews();candidateList.removeAllViews();JSONArray evidence=EvidenceReviewModel.arr(r,"evidence");for(int n=0;n<evidence.length();n++){final int index=n;JSONObject e=evidence.getJSONObject(n);evidenceList.addView(button("核对引用 "+e.optString("evidenceId","#"+(n+1))+" · "+e.optString("title"),()->readEvidence(index)));}JSONArray candidates=EvidenceReviewModel.arr(r,"candidates");Map<String,Integer> counts=new HashMap<>();for(int n=0;n<candidates.length();n++){String code=candidates.getJSONObject(n).optString("code");counts.put(code,counts.getOrDefault(code,0)+1);}for(int n=0;n<candidates.length();n++){JSONObject row=candidates.getJSONObject(n);int index=n;candidateList.addView(text((n+1)+". "+row.optString("code")+" "+row.optString("name")+(counts.get(row.optString("code"))>1?" · 重复代码原行":"")));candidateList.addView(button("核验 / 阅读完整候选",()->readCandidate(audit(row))));candidateList.addView(button("明确选择此行",()->{JSONObject a=audit(row);EvidenceReviewModel.require(a.optString("identityState").equals("exact"),"身份/名称未与本机目录精确一致；未选择");selected.put(index,a);markSelections();persist();status.setText("已明确选择 "+selected.size()+" 行；尚未保存候选");}));candidateList.addView(button("取消选择此行",()->{selected.remove(index);markSelections();persist();}));}}
 JSONObject audit(JSONObject row)throws Exception{String id=identity.getText().toString().trim();if(id.isEmpty())id=row.optString("instrumentId");return EvidenceReviewModel.audit(row,id,catalogue());}
 void readCandidate(JSONObject c)throws Exception{StringBuilder body=new StringBuilder(EvidenceReviewModel.readCandidate(c)+"\n引用核验\n");JSONArray ids=EvidenceReviewModel.arr(c,"evidenceIds"),all=EvidenceReviewModel.arr(report,"evidence");for(int n=0;n<ids.length();n++){String id=ids.getString(n);boolean found=false;for(int j=0;j<all.length();j++){JSONObject e=all.getJSONObject(j);if(!e.optString("evidenceId").equals(id))continue;found=true;JSONObject a=EvidenceReviewModel.citation(e,business.read("docs"),business.read("collections"));body.append(id).append("：").append(a.optString("message")).append('\n').append(EvidenceReviewModel.json(e)).append('\n');}if(!found)body.append(id).append("：报告中引用编号缺失\n");}if(ids.length()==0)body.append("此候选未提供明确引用编号，未推断关联\n");read(body.toString());}
 void readEvidence(int index)throws Exception{JSONObject e=SourceAnalysisPacket.copy(report.getJSONArray("evidence").getJSONObject(index));String bindingId="citation:"+SourceAnalysisPacket.hash(report.getString("id")+":"+index);JSONObject binding=store.get("bindings",bindingId);if(binding.length()>0)e.put("sourceRef",binding.getJSONObject("reference"));JSONObject audit=EvidenceReviewModel.citation(e,business.read("docs"),business.read("collections"));LinearLayout body=read(audit.optString("message")+"\n完整引用原文\n"+EvidenceReviewModel.json(e)+"\n本机当前完整来源（若存在）\n"+EvidenceReviewModel.json(EvidenceReviewModel.obj(audit,"current")));if(audit.optString("state").equals("exact")){body.addView(button("重新核验并打开冻结来源",()->{JSONObject ref=audit.getJSONObject("reference"),current=SourceAnalysisPacket.exactSource(ref,business.read(ref.getString("kind")));EvidenceReviewModel.require(opener!=null,"宿主未接来源入口");opener.open(ref.getString("kind"),current);}));}else if(audit.optString("state").equals("snippet-only")){body.addView(button("明确绑定当前完整来源版本（不宣称历史已证实）",()->{JSONObject fresh=EvidenceReviewModel.citation(e,business.read("docs"),business.read("collections"));EvidenceReviewModel.require(fresh.optString("state").equals("snippet-only")&&EvidenceReviewModel.json(fresh.getJSONObject("current")).equals(EvidenceReviewModel.json(audit.getJSONObject("current"))),"来源已变化，请重读引用");JSONObject row=SourceAnalysisPacket.copy(fresh.getJSONObject("current")).put("sourceKind","docs"),ref=new JSONObject().put("kind","docs").put("id",row.getString("id")).put("snapshot",SourceAnalysisPacket.snapshot(row)).put("bodyHash",SourceAnalysisPacket.hash(row.optString("text")+'\0'+row.optString("originalText")));store.put(new JSONObject().put("kind","bindings").put("id",bindingId).put("reportId",report.getString("id")).put("reportSnapshot",report).put("index",index).put("reference",ref).put("scope","manual-current-version-not-historical-proof"),binding.optString("recordRevision"));status.setText("已绑定当前完整版本；历史报告出处仍待核验");}));}style();}
 void refreshHistory()throws Exception{batchList.removeAllViews();JSONArray rows=store.list("batches",batchOffset);for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);batchList.addView(button(r.optString("title")+" · "+r.optString("approvedAt")+" · "+r.optInt("candidateCount")+"只",()->readBatch(r.getString("id"))));}}
 void readBatch(String id)throws Exception{JSONObject batch=store.get("batches",id);LinearLayout body=read("独立候选历史（未独立验证）\n"+EvidenceReviewModel.reviewText(batch.getJSONObject("reportSnapshot"),batch.getJSONArray("candidates"),business.read("docs"),business.read("collections"))+EvidenceReviewModel.json(batch));JSONArray rows=batch.getJSONArray("candidates");for(int n=0;n<rows.length();n++){JSONObject c=rows.getJSONObject(n);for(String kind:new String[]{"chart","watchlist"})body.addView(button((kind.equals("chart")?"打开K线 · ":"明确加入自选 · ")+c.optString("name")+" "+c.getString("instrumentId"),()->{JSONObject fresh=EvidenceReviewModel.audit(c,c.getString("instrumentId"),catalogue());EvidenceReviewModel.require(fresh.optString("identityState").equals("exact")&&action!=null,"身份已改变或宿主动作未接入");action.open(kind,fresh);}));}style();}
 LinearLayout read(String body){if(reader!=null)removeView(reader);readerY=mainScroll.getScrollY();mainScroll.setVisibility(GONE);reader=new ScrollView(context);LinearLayout content=vertical();reader.addView(content);addView(reader,new LayoutParams(-1,-1));content.addView(button("返回复核工作区（保留草稿）",()->back()));content.addView(text(body));style();return content;}
 boolean back(){if(reader==null)return false;removeView(reader);reader=null;mainScroll.setVisibility(VISIBLE);mainScroll.post(()->mainScroll.scrollTo(0,readerY));return true;}
 void setDarkTheme(boolean value){dark=value;style();}
 void style(){SourceHandoffPanel.styleTree(this,dark);}
}








